template:
% 参数由系统自动注入：\def\semimajor{3.5} \def\semiminor{2.2} \def\showcenter{1} \def\showaxes{1} \def\showfoci{1} \def\showvertices{1} \def\showpoint{0} \def\pointangle{55} \def\labelp{P} \def\showcoord{1} \def\cx{0} \def\cy{0}
% 焦点距 c = sqrt(a^2 - b^2)，须 a>b 故 c>0
\pgfmathsetmacro{\focal}{sqrt(\semimajor*\semimajor - \semiminor*\semiminor)}
% 椭圆上点 P 在椭圆方程上：给定角度 theta，半径 r = a*b / sqrt((b*cosθ)^2 + (a*sinθ)^2)
\pgfmathsetmacro{\pc}{cos(\pointangle)}
\pgfmathsetmacro{\ps}{sin(\pointangle)}
\pgfmathsetmacro{\den}{sqrt((\semiminor*\pc)*(\semiminor*\pc) + (\semimajor*\ps)*(\semimajor*\ps))}
\pgfmathsetmacro{\rpx}{\semimajor*\semiminor*\pc/\den}
\pgfmathsetmacro{\rpy}{\semimajor*\semiminor*\ps/\den}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(\cx - \semimajor - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(\cx + \semimajor + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \semiminor - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \semiminor + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{6 / (2*\semimajor)}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
% ===== 关键点绝对坐标预计算 =====
\pgfmathsetmacro{\oXabs}{\cx}
\pgfmathsetmacro{\oYabs}{\cy}
\pgfmathsetmacro{\foneXabs}{\cx - \focal}
\pgfmathsetmacro{\foneYabs}{\cy}
\pgfmathsetmacro{\ftwoXabs}{\cx + \focal}
\pgfmathsetmacro{\ftwoYabs}{\cy}
\pgfmathsetmacro{\aoneXabs}{\cx - \semimajor}
\pgfmathsetmacro{\aoneYabs}{\cy}
\pgfmathsetmacro{\atwoXabs}{\cx + \semimajor}
\pgfmathsetmacro{\atwoYabs}{\cy}
\pgfmathsetmacro{\boneXabs}{\cx}
\pgfmathsetmacro{\boneYabs}{\cy - \semiminor}
\pgfmathsetmacro{\btwoXabs}{\cx}
\pgfmathsetmacro{\btwoYabs}{\cy + \semiminor}
\pgfmathprintnumberto[precision=1,fixed]{\oXabs}{\oXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\oYabs}{\oYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\foneXabs}{\foneXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\foneYabs}{\foneYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\ftwoXabs}{\ftwoXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\ftwoYabs}{\ftwoYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\aoneXabs}{\aoneXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\aoneYabs}{\aoneYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\atwoXabs}{\atwoXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\atwoYabs}{\atwoYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\boneXabs}{\boneXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\boneYabs}{\boneYfmt}
\pgfmathprintnumberto[precision=1,fixed]{\btwoXabs}{\btwoXfmt}
\pgfmathprintnumberto[precision=1,fixed]{\btwoYabs}{\btwoYfmt}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \coordinate (O) at (\cx,\cy);
  \coordinate (F1) at (\cx-\focal,\cy);
  \coordinate (F2) at (\cx+\focal,\cy);
  % 长轴/短轴辅助线（先画，垫在椭圆下方）
  \ifnum\showaxes>0
    \draw[dashed, gray] (\cx-\semimajor,\cy) -- (\cx+\semimajor,\cy);
    \draw[dashed, gray] (\cx,\cy-\semiminor) -- (\cx,\cy+\semiminor);
  \fi
  % 椭圆曲线
  \draw[thick] (\cx,\cy) ellipse [x radius=\semimajor, y radius=\semiminor];
  % 椭圆上点 P 连两焦点（椭圆定义 PF1+PF2=2a）
  \ifnum\showpoint>0
    \draw[thick] (F1) -- (\cx+\rpx,\cy+\rpy) -- (F2);
    \fill (\cx+\rpx,\cy+\rpy) circle [radius=\dotr pt];
    \node at ({\cx+1.16*\rpx},{\cy+1.16*\rpy}) {$\labelp$};
  \fi
  % 焦点 F1/F2
  \ifnum\showfoci>0
    \fill (F1) circle [radius=\dotr pt];
    \fill (F2) circle [radius=\dotr pt];
    \node[below left=3pt] at (F1) {$F_1\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\foneXfmt, \foneYfmt)}\fi$};
    \node[below right=3pt] at (F2) {$F_2\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\ftwoXfmt, \ftwoYfmt)}\fi$};
  \fi
  % 四个顶点 A1/A2/B1/B2
  \ifnum\showvertices>0
    \fill (\cx-\semimajor,\cy) circle [radius=\dotr pt];
    \fill (\cx+\semimajor,\cy) circle [radius=\dotr pt];
    \fill (\cx,\cy-\semiminor) circle [radius=\dotr pt];
    \fill (\cx,\cy+\semiminor) circle [radius=\dotr pt];
    \node[above left=2pt] at (\cx-\semimajor,\cy) {$A_1\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\aoneXfmt, \aoneYfmt)}\fi$};
    \node[above right=2pt] at (\cx+\semimajor,\cy) {$A_2\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\atwoXfmt, \atwoYfmt)}\fi$};
    \node[below=2pt] at (\cx,\cy-\semiminor) {$B_1\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\boneXfmt, \boneYfmt)}\fi$};
    \node[above=2pt] at (\cx,\cy+\semiminor) {$B_2\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\btwoXfmt, \btwoYfmt)}\fi$};
  \fi
  % 中心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below right=2pt] at (O) {$O\ifnum\showpointcoord>0\ \textcolor{blue!60!black}{\scriptsize (\oXfmt, \oYfmt)}\fi$};
  \fi
\end{tikzpicture}
